// Class 10 Social Science practice bank, part 3: History (Rise of Nationalism in Europe, Nationalism in India, Making of a Global World, Age of Industrialisation, Print Culture). Extra board-style questions for year-long practice (unreviewed draft).
(function () {
  const AR_OPTS = ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."];
  let n = 3 - 1;
  // M(level, question, right answer, three wrong answers, explanation): the right answer is stored at a varying position.
  function M(level, q, right, wrong, explain) {
    const at = (n++) % 4;
    const options = wrong.slice();
    options.splice(at, 0, right);
    return { q, options, answer: at, explain, level };
  }
  // AR(level, assertion, reason, answer index, explanation): assertion-reason with fixed options.
  function AR(level, a, r, answer, explain) {
    return { q: "Assertion (A): " + a + "\nReason (R): " + r, options: AR_OPTS, answer, explain, level, keepOrder: true };
  }
  // W(marks, question, model answer, type?)
  function W(marks, q, a, type) {
    const o = { q, a, marks };
    if (type) o.type = type;
    return o;
  }
  StudyData.addPractice(10, "sst", {
  "rise-of-nationalism-in-europe": {
    mcq: [
      M(1, "The first clear expression of nationalism in Europe came with the", "French Revolution of 1789", ["Congress of Vienna of 1815", "Greek war of independence", "Frankfurt Parliament of 1848"], "In 1789 sovereignty passed from the monarch to the French citizens, the first clear expression of nationalism."),
      M(1, "Which flag replaced the royal standard of France after the revolution?", "The tricolour", ["The Union Jack", "The red flag with a crown", "The white flag with lilies"], "The revolutionaries adopted a new tricolour flag in place of the royal standard."),
      M(1, "Who was the chief minister of Prussia during the unification of Germany?", "Otto von Bismarck", ["Count Cavour", "Duke Metternich", "Giuseppe Mazzini"], "Bismarck led Prussia through wars with Austria, Denmark and France. Cavour was Sardinia-Piedmont's minister."),
      M(1, "In which year was Victor Emmanuel II proclaimed king of united Italy?", "1861", ["1859", "1848", "1871"], "Italy was proclaimed a kingdom in 1861; 1871 is the year of German unification."),
      M(1, "Which female figure was used as an allegory of the French nation?", "Marianne", ["Germania", "Italia", "Bharat Mata"], "Marianne, with a red cap and tricolour, stood for France. Germania was the German allegory."),
      M(1, "The Frankfurt Parliament of 1848 met in", "St Paul's Church", ["The Hall of Mirrors", "The Palace of Vienna", "The port of Marseilles"], "831 elected members met in St Paul's Church in Frankfurt to draft a constitution."),
      M(1, "Before its war of independence began in 1821, Greece was ruled by the", "Ottoman Empire", ["Austrian Empire", "Russian Empire", "Kingdom of France"], "Greeks rose against the Ottoman Empire, and Greece was recognised as independent in 1832."),
      M(1, "The word 'liberalism' comes from the Latin word liber, which means", "free", ["land", "law", "people"], "Liberalism stood for individual freedom, equality before law and government by consent."),
      M(2, "Which of these was abolished by the Civil Code of 1804?", "Privileges based on birth", ["Equality before the law", "The right to property", "Uniform weights and measures"], "The Code removed birth-based privileges and secured equality before law and the right to property."),
      M(2, "People in lands conquered by Napoleon lost their early enthusiasm for French rule mainly because of", "higher taxes and forced army service", ["the return of feudal dues on peasants", "the cancelling of the Civil Code", "the removal of all trade restrictions"], "Increased taxation, censorship and forced conscription turned support into hostility."),
      M(2, "The Zollverein reduced the number of currencies in the German states from over thirty to", "two", ["one", "five", "ten"], "The customs union abolished tariff barriers and cut the number of currencies to two."),
      M(2, "At the Congress of Vienna, which territory was added to Piedmont to strengthen a border state against France?", "Genoa", ["Belgium", "Prussia", "Marseilles"], "Genoa was added to Piedmont; Belgium went to the Kingdom of the Netherlands."),
      M(2, "Giuseppe Mazzini belonged to which secret society before founding Young Italy?", "The Carbonari", ["The Jacobins", "The Red Shirts", "The Zollverein"], "Mazzini, born in Genoa in 1807, was a member of the Carbonari."),
      M(2, "Which ruler refused the crown offered by the Frankfurt Parliament?", "Friedrich Wilhelm IV of Prussia", ["William I of Prussia", "Louis Philippe of France", "Victor Emmanuel II of Sardinia"], "He rejected the crown, and the liberal parliament was dissolved."),
      M(2, "The three wars fought by Prussia under Bismarck over seven years were against", "Austria, Denmark and France", ["Russia, Italy and Britain", "Spain, Poland and Austria", "Denmark, Sweden and Russia"], "Wars with Austria, Denmark and France led to German unification in 1871."),
      M(2, "How did the Grimm brothers contribute to German nationalism?", "They collected German folk tales", ["They drafted a constitution", "They led the Red Shirts", "They founded the Zollverein"], "Romantic nationalists used folk culture and folk tales to build a sense of a common German heritage."),
      M(2, "The Act of Union of 1707 was important because it", "joined England and Scotland", ["joined England and Ireland", "created a separate Welsh state", "ended the British monarchy"], "Ireland was brought in later, in 1801."),
      M(3, "Arrange in time order: (a) Congress of Vienna, (b) July Revolution in France, (c) Frankfurt Parliament, (d) William I proclaimed German Emperor.", "(a), (b), (c), (d)", ["(b), (a), (c), (d)", "(a), (c), (b), (d)", "(a), (b), (d), (c)"], "The dates are 1815, 1830, 1848 and 1871."),
      M(3, "Match the symbol with its meaning: (1) broken chains, (2) sword, (3) olive branch around the sword, (4) rays of the rising sun. Meanings: (P) willingness to make peace, (Q) readiness to fight, (R) being freed, (S) beginning of a new era.", "1-R, 2-Q, 3-P, 4-S", ["1-Q, 2-R, 3-P, 4-S", "1-R, 2-P, 3-Q, 4-S", "1-S, 2-Q, 3-P, 4-R"], "Broken chains mean freedom; a sword means readiness to fight; an olive branch means peace; the rising sun means a new era."),
      M(3, "Why did the Balkans become a zone of conflict after 1871?", "Rivalry among Balkan states and among the big powers", ["The absence of any Slav population in the region", "The spread of the Zollverein into the region", "The return of the Bourbon dynasty to the Balkans"], "Mainly Slav peoples left the weakening Ottoman Empire, and the powers competed for influence; this led towards the First World War."),
      AR(2, "Napoleon's rule brought some modernising reforms to the areas he conquered.", "He abolished the feudal system and freed peasants from serfdom and manorial dues there.", 0, "The abolition of feudalism and guild restrictions was a modernising change that explains the assertion."),
      AR(2, "The Zollverein helped economic unity among the German states.", "It was formed in 1834 at Prussia's initiative and abolished tariff barriers.", 0, "Removing tariff barriers and reducing the number of currencies made trade easier and bound the states economically."),
      AR(2, "In German pictures the nation Germania wears a crown of oak leaves.", "The oak leaf stands for heroism.", 0, "The crown of oak leaves shows heroism, which explains why Germania wears it."),
      AR(3, "Garibaldi's Red Shirts were mainly responsible for defeating Austria in northern Italy in 1859.", "Garibaldi marched into South Italy and the Kingdom of the Two Sicilies in 1860.", 3, "Sardinia-Piedmont, helped by Cavour's alliance with France, defeated Austria in 1859. Garibaldi's march was in the south in 1860."),
      AR(3, "Britain became a nation-state through a sudden revolution.", "The Act of Union of 1707 joined England and Scotland.", 3, "The British nation-state grew slowly: 1707 for England and Scotland, 1801 for Ireland. There was no single revolution."),
    ],
    written: [
      W(2, "State any two features of the Napoleonic Code of 1804.", "It did away with privileges based on birth.\nIt established equality before the law and secured the right to property."),
      W(2, "Who was Giuseppe Mazzini? Name two organisations he founded.", "Mazzini was an Italian revolutionary born in Genoa in 1807 and a member of the Carbonari.\nHe founded Young Italy in Marseilles and Young Europe in Berne."),
      W(2, "Why is the Treaty of Constantinople (1832) important in the history of European nationalism?", "It recognised Greece as an independent nation after the war of independence that began in 1821 against the Ottoman Empire.\nThe struggle roused nationalist feelings among educated Europeans."),
      W(2, "What is an allegory? Name the allegorical figures of France and Germany.", "An allegory expresses an abstract idea such as liberty or the nation through a person or thing.\nMarianne stands for France and Germania for Germany."),
      W(3, "Explain the meaning of liberalism in the political and the economic sphere in the early nineteenth century.", "Political: freedom for the individual, equality before law, government by consent, a constitution and representative government. Voting rights were limited to property-owning men.\nEconomic: freedom of markets and the end of state restrictions on the movement of goods and capital.\nExample: the Zollverein of 1834 abolished tariff barriers and reduced the number of currencies."),
      W(3, "Describe three features of the settlement made at the Congress of Vienna in 1815.", "It was hosted by the Austrian chancellor Duke Metternich after Napoleon's defeat.\nThe Bourbon dynasty was restored in France and Napoleon's conquests were taken away.\nStates were set up on France's borders to check expansion, e.g. the Kingdom of the Netherlands (with Belgium) and Genoa added to Piedmont."),
      W(3, "Describe the revolutions of 1848 in Europe. Why did the Frankfurt Parliament fail?", "In 1848 there were revolts of the poor, who faced unemployment and food shortages, and of the educated middle classes who wanted a constitution.\nThe Frankfurt Parliament, of 831 elected members meeting in St Paul's Church, drafted a constitution for a German nation.\nIt failed because Friedrich Wilhelm IV of Prussia rejected the crown, and the monarchy and army joined forces against the parliament."),
      W(3, "How was Britain's nation-state formed? Give three points.", "It was a long process and not a sudden revolution.\nThe Act of Union (1707) joined England and Scotland; Ireland was forcibly incorporated in 1801.\nA British identity was built around symbols such as the Union Jack, the national anthem and the English language."),
      W(5, "'After 1871 nationalism in Europe became a narrow creed.' Explain this statement with reference to the Balkans and the First World War.", "Nationalism lost its liberal and idealistic character and was used by imperialist powers to justify colonies.\nThe Balkans (Romania, Bulgaria, Greece, Serbia, Montenegro, Bosnia-Herzegovina and others) were inhabited mainly by Slavs and were under the Ottoman Empire.\nAs Ottoman control weakened, the Balkan states fought each other, each claiming more territory.\nRussia, Germany, England and Austro-Hungary competed for influence over the area.\nThese rivalries led to a series of wars and finally to the First World War in 1914."),
      W(4, "Case study: After Napoleon's armies entered a town in a conquered region, the local peasants were freed from manorial dues, guild restrictions were removed and the administration became simpler. After a few years, however, the townspeople complained about heavy taxes, strict censorship and young men being taken for the French army.\n(i) Name the law code that spread these reforms. (1)\n(ii) State two reforms made in the conquered areas. (2)\n(iii) Why did the people's enthusiasm turn into hostility? (1)", "(i) The Civil Code of 1804 (Napoleonic Code). (1)\n(ii) Any two: the feudal system and serfdom were abolished; guild restrictions were removed; administrative divisions were simplified. (2)\n(iii) Because of increased taxation, censorship and forced conscription into the French armies. (1)", "case"),
    ]
  },
  "nationalism-in-india": {
    mcq: [
      M(1, "Gandhiji returned to India from South Africa in", "January 1915", ["January 1905", "April 1919", "March 1921"], "He came back in January 1915 and soon began local satyagrahas."),
      M(1, "The Kheda Satyagraha of 1917 was fought for", "relaxation of revenue", ["abolition of the salt tax", "higher wages for mill workers", "an end to the plantation system"], "Kheda in Gujarat sought relief from revenue after crop failure. Ahmedabad was about mill workers and Champaran about plantations."),
      M(1, "Gandhiji called a nationwide hartal against the Rowlatt Act on", "6 April 1919", ["13 April 1919", "26 January 1930", "5 March 1931"], "The hartal was on 6 April 1919; the Jallianwala Bagh firing came a week later."),
      M(1, "The militant guerrilla movement of the Gudem Hills in Andhra was led by", "Alluri Sitaram Raju", ["Baba Ramchandra", "Subhas Chandra Bose", "C.R. Das"], "He led tribals against restrictions on forest use. Baba Ramchandra led peasants in Awadh."),
      M(1, "The Swaraj Party within the Congress was formed by", "C.R. Das and Motilal Nehru", ["Muhammad Ali and Shaukat Ali", "Jawaharlal Nehru and Subhas Bose", "Baba Ramchandra and Alluri Raju"], "They wanted the Congress to return to council politics."),
      M(1, "The Salt March from Sabarmati to Dandi covered a distance of over", "240 miles", ["24 miles", "100 miles", "1,000 miles"], "Gandhiji and 78 volunteers walked over 240 miles to Dandi."),
      M(1, "Who wrote the novel Anandamath, which includes the song 'Vande Mataram'?", "Bankim Chandra Chattopadhyay", ["Rabindranath Tagore", "Abanindranath Tagore", "Natesa Sastri"], "Bankim Chandra wrote the song in the 1870s and later included it in Anandamath."),
      M(1, "The Swaraj flag designed by 1921 carried at its centre a", "spinning wheel", ["set of eight lotuses", "rising sun", "open palm"], "The spinning wheel stood for Gandhiji's idea of self-help. The eight lotuses were on the Swadeshi tricolour."),
      M(2, "The Khilafat Committee was formed in Bombay in March 1919 under the leadership of", "Muhammad Ali and Shaukat Ali", ["Alluri Sitaram Raju and Baba Ramchandra", "B.R. Ambedkar and Gandhiji", "Jawaharlal Nehru and Subhas Bose"], "The Ali brothers formed it to defend the Ottoman Khalifa."),
      M(2, "Why did Gandhiji support the Khilafat cause?", "He hoped to unite Hindus and Muslims", ["He wanted separate electorates for Muslims", "He wished to end the salt tax", "He wanted to oppose the Simon Commission"], "Gandhiji hoped the Khilafat issue would bring Hindus and Muslims together against British rule."),
      M(2, "During the Non-Cooperation Movement, council elections were boycotted everywhere except in", "Madras", ["Bengal", "Punjab", "Bombay"], "In Madras the non-Brahman Justice Party contested the elections, seeing councils as a way to gain power."),
      M(2, "Under the Inland Emigration Act of 1859, plantation workers in Assam were", "tied to the tea gardens", ["free to return home at any time", "given land by the government", "paid fixed wages by the Congress"], "Many workers defied this, left the gardens and headed home, believing 'Gandhi Raj' was coming."),
      M(2, "Between 1921 and 1922, the import of foreign cloth into India", "halved", ["doubled", "rose slightly", "stayed the same"], "Boycott and the burning of foreign cloth cut the imports by half."),
      M(2, "In October 1929 Viceroy Lord Irwin announced", "a vague offer of dominion status", ["immediate independence for India", "the withdrawal of the Rowlatt Act", "separate electorates for the Depressed Classes"], "The offer did not satisfy radical leaders, and the Lahore Congress soon demanded Purna Swaraj."),
      M(2, "Under the Gandhi-Irwin Pact of March 1931, Gandhiji agreed to", "attend the Second Round Table Conference", ["restart the Non-Cooperation Movement", "sign the Poona Pact with Ambedkar", "accept the Simon Commission report"], "He went to London in December 1931, but the conference failed."),
      M(2, "The Federation of Indian Chambers of Commerce and Industry (FICCI) was formed in", "1927", ["1917", "1930", "1935"], "Indian businessmen formed FICCI in 1927, and many supported the Civil Disobedience Movement."),
      M(2, "Abanindranath Tagore is remembered in this chapter for his painting of", "Bharat Mata", ["the Salt March", "Jallianwala Bagh", "Mother India's flag"], "His painting of Bharat Mata became one of the best-known images of the motherland."),
      M(3, "Arrange in time order: (a) Gandhi-Irwin Pact, (b) Lahore Congress demands Purna Swaraj, (c) Chauri Chaura, (d) arrival of the Simon Commission.", "(c), (d), (b), (a)", ["(d), (c), (b), (a)", "(c), (b), (d), (a)", "(c), (d), (a), (b)"], "The dates are 1922, 1928, December 1929 and 1931."),
      M(3, "Match leader with movement: (1) Baba Ramchandra, (2) Alluri Sitaram Raju, (3) Dr B.R. Ambedkar, (4) Shaukat Ali. Movements: (P) Gudem Hills, (Q) Depressed Classes and the Poona Pact, (R) Awadh peasants, (S) Khilafat Committee.", "1-R, 2-P, 3-Q, 4-S", ["1-P, 2-R, 3-Q, 4-S", "1-R, 2-P, 3-S, 4-Q", "1-Q, 2-P, 3-R, 4-S"], "Baba Ramchandra led Awadh peasants; Raju the Gudem Hills; Ambedkar the Depressed Classes; Shaukat Ali the Khilafat Committee."),
      M(3, "The fall in agricultural prices after 1930 pushed peasants towards the Civil Disobedience Movement mainly because", "the government still demanded the same revenue", ["they wanted separate electorates", "they preferred factory-made cloth", "the Simon Commission had changed the land laws"], "Prices collapsed with the Depression but the revenue demand was not reduced, so peasants could not pay."),
      AR(2, "The Rowlatt Act was strongly opposed by Indians.", "It allowed detention of political prisoners without trial for two years.", 0, "Detention without trial took away basic rights, which is why the Act was resented."),
      AR(2, "The Non-Cooperation Movement slowed down in the cities.", "Khadi cloth was more expensive than mill cloth, and alternative Indian institutions came up slowly.", 0, "Poor people could not afford khadi, and boycotted schools and courts were not quickly replaced."),
      AR(3, "In the Civil Disobedience Movement people were asked to break colonial laws.", "In Hind Swaraj Gandhiji wrote that British rule survived only because Indians cooperated.", 1, "Both are true, but the idea of non-cooperation in Hind Swaraj does not explain why law-breaking was added in 1930."),
      AR(3, "The Poona Pact gave separate electorates to the Depressed Classes.", "Under it, seats were reserved for them but voted by the general electorate.", 3, "The Pact gave reserved seats, not separate electorates, so the assertion is false."),
      AR(2, "The Lahore Congress of 1929 demanded Purna Swaraj.", "In October 1929 Lord Irwin had made only a vague offer of dominion status.", 1, "Both are true; the vague offer was one reason for impatience, but the Lahore demand was also shaped by radical pressure from younger leaders."),
    ],
    written: [
      W(2, "Name any two early satyagrahas of Gandhiji in India and the cause of each.", "Champaran (Bihar, 1917): against the oppressive plantation system.\nKheda (Gujarat, 1917): for relaxation of revenue after crop failure. (Ahmedabad, 1918, for cotton mill workers, may also be given.)"),
      W(2, "What was the book Hind Swaraj (1909)? State its central idea.", "It was a book by Gandhiji, written in 1909.\nIt argued that British rule survived only because of Indian cooperation; if Indians refused to cooperate, it would collapse."),
      W(2, "Why did the peasants of Awadh rise against the talukdars?", "Talukdars and landlords demanded very high rents and many other cesses.\nPeasants had to do begar (forced labour without payment) and had no security of tenure; the Oudh Kisan Sabha was set up in October 1920."),
      W(2, "How did the Assam plantation workers understand the Non-Cooperation Movement?", "Under the Inland Emigration Act of 1859 they could not leave the tea gardens without permission.\nThey believed that 'Gandhi Raj' was coming and that they would get land in their own villages, so they left the plantations."),
      W(3, "State the three stages of the Non-Cooperation programme proposed by Gandhiji.", "First, surrender of titles given by the government.\nSecond, boycott of civil services, army, police, courts, legislative councils, schools and foreign goods.\nThird, a full civil disobedience campaign if the government used repression."),
      W(3, "Explain three ways in which the First World War created difficulties for Indians.", "Defence expenditure rose and was met by war loans and higher taxes; income tax was introduced.\nPrices doubled between 1913 and 1918, hurting the common people.\nVillages were forced to supply recruits to the army; crop failures and an influenza epidemic added to the suffering."),
      W(3, "Map-based question (in words): Name the state in which each of the following places is now located: (a) Champaran, (b) Kheda, (c) Chauri Chaura.", "(a) Champaran: Bihar.\n(b) Kheda: Gujarat.\n(c) Chauri Chaura (near Gorakhpur): Uttar Pradesh.", "short"),
      W(3, "Map-based question (in words): Name the city where each Congress session was held: (a) the session of September 1920 that approved Non-Cooperation, (b) the session of December 1920 that adopted it, (c) the session of December 1929 that demanded Purna Swaraj.", "(a) Calcutta.\n(b) Nagpur.\n(c) Lahore.", "short"),
      W(5, "Explain the developments between 1922 and 1930 that led to the Civil Disobedience Movement.", "The Swaraj Party was formed by C.R. Das and Motilal Nehru to return to council politics, while Jawaharlal Nehru and Subhas Bose pressed for more radical mass agitation.\nAgricultural prices fell from 1926 and collapsed after 1930 because of the world depression, causing distress.\nThe Simon Commission arrived in 1928 with no Indian member and was met with 'Go back Simon'.\nIn October 1929 Irwin made only a vague offer of dominion status.\nThe Lahore Congress (December 1929) under Nehru demanded Purna Swaraj, and 26 January 1930 was observed as Independence Day; then Gandhiji began the Salt March."),
      W(4, "Case study: In 1921 a young Congress volunteer in a small town hoisted a flag with red, green and white bands and a spinning wheel in the centre. Nearby, a poster showed a calm figure of Bharat Mata holding a book and a sheaf of rice. People gathered and sang Vande Mataram.\n(i) Who designed the Swaraj flag? Name the symbol at its centre. (1)\n(ii) Who painted the well-known image of Bharat Mata? (1)\n(iii) How did flags and images help create a sense of collective belonging? (2)", "(i) The Swaraj flag was designed by Gandhiji; the spinning wheel was at the centre, standing for self-help. (1)\n(ii) Abanindranath Tagore. (1)\n(iii) Any two: they gave people a common symbol to identify with; carrying flags during marches expressed defiance; the images of Bharat Mata and the song Vande Mataram stirred love for the motherland and united people across regions. (2)", "case"),
    ]
  },
  "making-of-a-global-world": {
    mcq: [
      M(1, "The silk routes got their name from", "the Chinese silk carried along them", ["the silk farms of Bengal", "the silk mills of Surat", "the silkworms of Japan"], "Chinese silk and pottery travelled west on these routes, while Indian textiles and spices also moved along them."),
      M(1, "The failure of which crop caused a famine in Ireland in the mid-1840s?", "Potato", ["Maize", "Wheat", "Tomato"], "The poorest Irish peasants depended on potatoes, and a disease destroyed the crop."),
      M(1, "At the Berlin Conference of 1885 European powers divided up", "Africa", ["India", "South America", "South-East Asia"], "They met to complete the carving up of Africa among themselves."),
      M(1, "Henry Ford is known for introducing the", "assembly line", ["steam engine", "telegraph", "Corn Laws"], "Ford's assembly line made cars quicker and cheaper to produce."),
      M(1, "The IMF and the World Bank began their financial operations in", "1947", ["1944", "1939", "1952"], "They were set up at Bretton Woods in July 1944 but started operating in 1947."),
      M(1, "Which disease helped the Spanish and Portuguese conquer the native peoples of America?", "Smallpox", ["Cholera", "Rinderpest", "Dengue"], "Native Americans had no immunity against European germs such as smallpox."),
      M(1, "Indentured labour migration from India was abolished in", "1921", ["1885", "1914", "1947"], "The system of long, contract-bound migration was stopped in 1921."),
      M(1, "The Great Depression began around the year", "1929", ["1914", "1939", "1945"], "It started around 1929 and lasted until the mid-1930s."),
      M(2, "About how many people emigrated from Europe to America and Australia in the nineteenth century?", "50 million", ["5 million", "15 million", "100 million"], "Nearly 50 million Europeans left in search of work and land."),
      M(2, "After the Corn Laws were scrapped, British agriculture", "lost out to cheap imports", ["earned higher prices for corn", "expanded into new cities", "was protected by new tariffs"], "Food imports became cheap, farming became unprofitable, and many people moved to cities or overseas."),
      M(2, "'Chutney music' is associated with", "Trinidad and Guyana", ["Fiji and Mauritius", "Ceylon and Malaya", "Kenya and Uganda"], "Indian migrants blended their traditions with local ones, creating Hosay, chutney music and other forms."),
      M(2, "Which community of Indian bankers financed export agriculture in Central and South-East Asia?", "Nattukottai Chettiars", ["Gomasthas", "Jobbers", "Staplers"], "Shikaripuri shroffs and Nattukottai Chettiars gave loans for export agriculture."),
      M(2, "'Capital flow' in an international economy means", "investment over long distances", ["movement of people looking for work", "trade in goods", "exchange of currencies"], "The three flows are trade (goods), labour (migration) and capital (investment)."),
      M(2, "Which of these fought on the side of the Central Powers in the First World War?", "Ottoman Turkey", ["France", "Russia", "Britain"], "The Central Powers were Germany, Austria-Hungary and Ottoman Turkey."),
      M(2, "The Axis powers in the Second World War were Germany, Italy and", "Japan", ["the Soviet Union", "France", "the United States"], "The Allies were Britain, France, the Soviet Union and the US."),
      M(2, "The World Bank (IBRD) was set up mainly to", "finance post-war reconstruction", ["fix the price of gold", "settle trade deficits", "control tariff rates"], "The IMF dealt with deficits and surpluses; the World Bank financed reconstruction."),
      M(2, "The G-77 countries demanded a", "New International Economic Order", ["Bretton Woods system", "gold standard", "Common Market"], "They wanted control over their resources, fair prices for raw materials and better market access."),
      M(3, "Arrange in time order: (a) Great Depression begins, (b) Berlin Conference, (c) Bretton Woods Conference, (d) end of indentured migration.", "(b), (d), (a), (c)", ["(b), (a), (d), (c)", "(d), (b), (a), (c)", "(b), (d), (c), (a)"], "The dates are 1885, 1921, 1929 and 1944."),
      M(3, "Match: (1) Corn Laws, (2) Rinderpest, (3) Bretton Woods, (4) Hosay. With: (P) cattle disease in Africa, (Q) Trinidad, (R) restriction on imports of corn, (S) IMF.", "1-R, 2-P, 3-S, 4-Q", ["1-P, 2-R, 3-S, 4-Q", "1-R, 2-P, 3-Q, 4-S", "1-S, 2-P, 3-R, 4-Q"], "The Corn Laws restricted corn imports; rinderpest hit African cattle; the IMF came from Bretton Woods; Hosay is a Trinidad festival."),
      M(3, "Indian wheat prices fell by 50 per cent between 1928 and 1934, while the colonial government did not cut revenue demands. The most likely result for peasants was", "greater debt and loss of land", ["higher incomes and savings", "a sharp increase in exports", "reduced revenue demands"], "Falling prices with fixed revenue pushed peasants into debt."),
      AR(2, "Rinderpest forced many Africans to become wage labourers.", "It killed about 90 per cent of the cattle on which their livelihoods depended.", 0, "With their cattle dead, Africans lost their independent livelihood and had to work for wages."),
      AR(2, "The potato was originally a crop of Europe.", "Potatoes reached Europe from America after Columbus's voyages.", 3, "Potato came from America to Europe, so the assertion is false."),
      AR(2, "Several banks collapsed during the Great Depression.", "Many countries depended on US loans, which were withdrawn when the US economy weakened.", 0, "The withdrawal of US loans caused failures of banks in many countries."),
      AR(3, "Britain imported more food after the Corn Laws were scrapped.", "Food from abroad was cheaper than food grown in Britain.", 0, "Cheaper foreign food increased imports and reduced demand for British-grown corn."),
      AR(3, "The Bretton Woods system lasted unchanged into the twenty-first century.", "Floating exchange rates were adopted after the system weakened from the 1960s.", 3, "The fixed-rate system weakened and floating rates were adopted, so the assertion is false."),
    ],
    written: [
      W(2, "Apart from goods, what else travelled along the silk routes? Give two examples.", "Ideas and religion: Buddhism spread from eastern India, and Christian missionaries and Muslim preachers also travelled by these routes.\nGerms and diseases also travelled, along with foods and skills."),
      W(2, "What was the Berlin Conference of 1885?", "It was a meeting of European powers.\nIts purpose was to complete the carving up of Africa among themselves."),
      W(2, "Distinguish between fixed and floating exchange rates.", "Fixed exchange rates are set by governments and linked to a standard such as gold or the dollar.\nFloating exchange rates are determined by the demand and supply of currencies in the market."),
      W(2, "Why did the poorest peasants in Ireland suffer so heavily in the mid-1840s?", "They had become heavily dependent on potatoes as their main food.\nWhen disease destroyed the potato crop, hundreds of thousands died of starvation."),
      W(3, "Explain three effects of rinderpest in Africa.", "It arrived in the late 1880s with infected cattle brought for Italian soldiers in Eritrea and reached the Atlantic coast by 1892.\nIt killed about 90 per cent of the cattle, destroying people's livelihood.\nAfricans, with no cattle, were forced to take up wage labour, and colonisers used this to strengthen their control."),
      W(3, "How did the Corn Laws and their repeal affect Britain's economy and society?", "The Corn Laws restricted the import of corn and kept food prices high.\nUnder pressure from industrialists and townspeople they were scrapped, and cheap food was imported.\nBritish farming could not compete; people migrated to cities or overseas, and land was cleared abroad to meet British food demand."),
      W(3, "Describe the part played by Indian bankers and by Britain's trade surplus with India in the nineteenth-century world economy.", "Shikaripuri shroffs and Nattukottai Chettiars financed export agriculture in Central and South-East Asia.\nBritain had a trade surplus with India, and the earnings helped Britain settle its deficits with other countries.\nIndia also paid 'home charges' to Britain, so a large part of its earnings did not benefit Indians."),
      W(3, "Why did the developing countries form the G-77, and what did they demand?", "The Bretton Woods system was controlled by the Western industrial powers, and newly independent nations did not benefit.\nThey formed the G-77 and demanded a New International Economic Order.\nThey wanted real control over their resources, fairer prices for raw materials and better access to markets."),
      W(5, "How did the discovery of sea routes and the conquest of America in the sixteenth century change world trade and wealth?", "European sailors found sea routes to Asia and the Americas, which opened up new areas for trade.\nSilver from mines in present-day Peru and Mexico increased Europe's wealth and financed its trade with Asia.\nCrops of America such as potatoes, maize, tomatoes, chillies and sweet potatoes spread to Europe and Asia.\nThe Portuguese and Spanish conquest succeeded mainly because of germs such as smallpox, to which the native people had no immunity.\nTill the eighteenth century China and India were among the richest countries; later the centre of world trade shifted to Europe."),
      W(4, "Case study: A farm family in Ireland grew potatoes on a tiny plot and had little else to eat. In the mid-1840s a plant disease turned the crop black in the fields. Neighbours watched helplessly as the food ran out.\n(i) Name the crop and say where it originally came from. (1)\n(ii) Why were such families so badly affected? (1)\n(iii) State two consequences of the crop failure. (2)", "(i) Potato; it came to Europe from America after Columbus. (1)\n(ii) They depended almost entirely on potatoes for food and had no other crop or income. (1)\n(iii) Any two: hundreds of thousands died of starvation; many people emigrated; the poorest peasants were left destitute. (2)", "case"),
    ]
  },
  "age-of-industrialisation": {
    mcq: [
      M(1, "The earliest factories in England came up by the", "1730s", ["1630s", "1830s", "1930s"], "Cotton became the symbol of the new age."),
      M(1, "Which of these industries changed only slowly because new technology was costly and spread slowly?", "Pottery", ["Cotton", "Steam engines", "Iron and steel"], "Cotton and metal industries grew fastest, while traditional industries like pottery, furniture and food processing changed slowly."),
      M(2, "James Watt improved the design of a steam engine first built by", "Newcomen", ["Arkwright", "Hargreaves", "Boulton"], "Watt improved Newcomen's engine and patented his version in 1781."),
      M(1, "Which port on the Gujarat coast declined by the 1750s?", "Surat", ["Masulipatam", "Bombay", "Calcutta"], "Surat and Hoogly declined while Bombay and Calcutta grew."),
      M(1, "Which pair of ports grew under European companies after the 1750s?", "Bombay and Calcutta", ["Surat and Hoogly", "Surat and Masulipatam", "Hoogly and Masulipatam"], "The old ports of Indian merchants declined, and the new colonial ports took their place."),
      M(1, "The first jute mill in Bengal came up in", "1855", ["1754", "1874", "1917"], "The first jute mill started in 1855. The first cotton mill in Bombay was set up in 1854."),
      M(1, "The Elgin Mill was set up in", "Kanpur", ["Bombay", "Madras", "Calcutta"], "It was established in Kanpur in the 1860s."),
      M(1, "Labels showing Indian gods and goddesses on Manchester cloth were meant to", "make the cloth look familiar", ["show the price of cloth", "hide the maker's name", "advertise only to foreigners"], "The images linked foreign cloth with divine approval and made it acceptable."),
      M(2, "Who set up six joint-stock companies in Bengal in the 1830s and 1840s?", "Dwarkanath Tagore", ["Dinshaw Petit", "Seth Hukumchand", "J.N. Tata"], "His enterprises were funded by trade with China."),
      M(2, "Early Indian entrepreneurs such as Dwarkanath Tagore often made money through trade with", "China", ["Africa", "Russia", "Brazil"], "Dwarkanath Tagore, Dinshaw Petit and J.N. Tata made their money in the China trade before investing in industry."),
      M(2, "A stapler in the woollen trade was a person who", "sorted wool according to its fibre", ["dyed woollen cloth", "wove cloth on looms", "bought raw cotton from India"], "The stapler's sorted wool went to spinners, weavers and fullers."),
      M(2, "Why did merchants of Europe shift production to the countryside in proto-industrialisation?", "Guilds limited entry to trades", ["Town people refused to buy cloth", "There were no towns", "The Church banned work in towns"], "Guilds restricted the entry of new people and fixed prices and production."),
      M(2, "During the American Civil War Indian weavers were hit because", "raw cotton became very costly", ["exports to America rose", "the Company gave bigger advances", "Manchester closed its mills"], "Britain bought Indian raw cotton, and its price shot up for weavers."),
      M(2, "What was one effect of the Swadeshi movement on Indian industry?", "Demand for Indian mill cloth rose", ["Handlooms were banned across the country", "Imports of Manchester cloth rose steadily", "Mills in Bombay were closed down"], "Swadeshi pushed people to buy Indian goods, helping mills."),
      M(2, "The fly shuttle helped handloom weavers by", "raising their output", ["replacing jobbers", "ending seasonal demand", "closing the mills"], "New technology like the fly shuttle helped handloom production expand."),
      M(2, "Calendars were valuable to advertisers because they", "reached people who could not read", ["were very costly to buy", "listed prices only", "were sold only in towns"], "Calendars were hung in tea shops and homes, and even illiterate people saw the pictures."),
      M(2, "Advertisements of Indian manufacturers often urged people to", "buy swadeshi goods", ["buy cheaper foreign goods", "use only handmade imports", "avoid cloth altogether"], "Their message was that to care for the nation one should buy goods made by Indians."),
      M(3, "Arrange in time order: (a) first cotton mill in Bombay, (b) Watt patents his steam engine, (c) first jute mill in Bengal, (d) Seth Hukumchand's jute mill in Calcutta.", "(b), (a), (c), (d)", ["(a), (b), (c), (d)", "(b), (c), (a), (d)", "(b), (a), (d), (c)"], "The dates are 1781, 1854, 1855 and 1917."),
      M(3, "Match: (1) Arkwright, (2) Hargreaves, (3) Watt, (4) Hukumchand. With: (P) spinning jenny, (Q) improved steam engine, (R) cotton mill, (S) jute mill in Calcutta.", "1-R, 2-P, 3-Q, 4-S", ["1-P, 2-R, 3-Q, 4-S", "1-R, 2-Q, 3-P, 4-S", "1-S, 2-P, 3-Q, 4-R"], "Arkwright created the cotton mill; Hargreaves devised the jenny; Watt improved the steam engine; Hukumchand set up a jute mill."),
      M(3, "In the nineteenth century the handloom sector in India was badly hit at first mainly because", "cheap machine cloth flooded in", ["Indian cotton ceased to grow", "the Company stopped buying cloth", "guilds banned weaving"], "Manchester cloth made the export market collapse and the local market shrink."),
      AR(2, "Gomasthas often clashed with the weavers.", "Advances tied weavers to the Company and gomasthas supervised them strictly.", 0, "Strict supervision and the loss of freedom to sell to other buyers caused conflict."),
      AR(2, "Cotton mills in India grew rapidly during the First World War.", "Manchester imports fell and Indian mills got orders to supply war needs.", 0, "With fewer imports and more demand, Indian factories expanded."),
      AR(3, "Handloom weaving disappeared in India after factories came up.", "Technology such as the fly shuttle helped handloom weavers improve output.", 3, "Handloom production survived and even expanded, so the assertion is false."),
      AR(2, "Advertisements create new needs.", "They make products appear desirable and necessary.", 0, "By making goods look attractive and essential, advertisements shape minds."),
      AR(3, "Proto-industrialisation developed in the countryside rather than in towns.", "Town guilds were powerful and restricted production and new entrants.", 0, "Merchants could not expand under guild control, so they turned to peasants and artisans in villages."),
    ],
    written: [
      W(2, "How did advances given by the East India Company affect Indian weavers?", "Weavers took advances to buy raw material and were not free to sell cloth to other buyers.\nThe system tied them to the Company and made them dependent on it."),
      W(2, "Name two Indian entrepreneurs of the nineteenth century who made money in the China trade and state what they did with the money.", "Dwarkanath Tagore set up six joint-stock companies in Bengal in the 1830s and 1840s.\nDinshaw Petit and Jamsetjee Nusserwanjee Tata of Bombay invested in industry."),
      W(2, "How did labels help Manchester manufacturers sell cloth in India?", "The label 'Made in Manchester' assured buyers of quality.\nImages of Indian gods and goddesses made the product familiar and acceptable to Indian buyers."),
      W(2, "Why did the upper classes in Britain prefer handmade goods?", "Handmade products were a symbol of refinement and class.\nMachine-made goods were seen as ordinary and were mostly exported to the colonies."),
      W(3, "Explain three reasons for the decline of Indian textile exports in the nineteenth century.", "Cheap machine-made cloth from Manchester flooded the Indian market and the export market collapsed.\nThe old Indian-merchant trade network broke down and ports like Surat and Hoogly declined.\nThe Company's control over weavers through gomasthas and advances reduced their freedom and income."),
      W(3, "Who were jobbers? Explain their role in Indian factories.", "A jobber was an old, trusted worker employed by industrialists to recruit workers.\nHe usually brought people from his own village and made sure they had jobs.\nOver time he gained power, controlled the workers and demanded money and gifts."),
      W(3, "Why did new technology spread slowly in Britain, even in the age of industrialisation? Give three reasons.", "Machines were expensive and merchants and industrialists were cautious about using them.\nThe machines often broke down and repairs were costly.\nThere was plenty of cheap labour, and many industries had seasonal demand, so hand labour suited them."),
      W(3, "Map-based question (in words): Name the port of each region that was an important centre of the Indian textile trade before the 1750s: (a) Gujarat, (b) Coromandel coast, (c) Bengal.", "(a) Surat.\n(b) Masulipatam.\n(c) Hoogly.", "short"),
      W(5, "What is proto-industrialisation? Explain its working and why it suited merchants, peasants and artisans.", "It was large-scale production for an international market in the countryside before factories.\nMerchants moved to the countryside because the town guilds were powerful and restricted production and new entrants.\nMerchants supplied raw material, for example wool bought from a stapler, to spinners, weavers and fullers and had the cloth finished in London.\nPeasants and artisans earned extra income while still cultivating their small plots, using family labour.\nMerchants gained cheap labour and freedom from guilds, and they expanded production for the market."),
      W(4, "Case study: A weaver in the Carnatic region in the 1790s took an advance from a gomastha and agreed to supply cloth only to the Company. When the gomastha rejected some of his cloth and punished him, he left his village and moved to another place where he started weaving independently.\n(i) Who were gomasthas? (1)\n(ii) Why did the Company appoint them? (2)\n(iii) What did the weaver's action show? (1)", "(i) Gomasthas were paid servants of the East India Company. (1)\n(ii) To supervise weavers, collect supplies of cloth and examine the quality of cloth. (2)\n(iii) That weavers resisted the Company's control; in places in the Carnatic and Bengal they deserted their villages. (1)", "case"),
    ]
  },
  "print-culture-and-the-modern-world": {
    mcq: [
      M(1, "Which of these countries was among the earliest to develop print technology?", "China", ["Italy", "Germany", "Portugal"], "Print technology developed first in China, Japan and Korea, using woodblocks."),
      M(1, "Gutenberg took which machine as the model for his printing press?", "The olive press", ["The loom", "The water mill", "The paper mill"], "He adapted the olive press, and made metal moulds to cast the letters."),
      M(1, "Johann Gutenberg, the developer of the first known printing press, came from", "Strasbourg", ["Genoa", "Marseilles", "Berne"], "He worked in the German town of Strasbourg and developed the press in the 1430s."),
      M(1, "In France, small books with blue covers printed on poor paper were called the", "Bibliothèque Bleue", ["Chapbooks", "Ukiyo", "Gazettes"], "They were cheap books for the poor. Chapbooks were their English cousins."),
      M(1, "Who started the Bengali weekly Sambad Kaumudi in 1821?", "Rammohun Roy", ["James Hickey", "Bal Gangadhar Tilak", "Jyotiba Phule"], "Orthodox Hindus replied with Samachar Chandrika."),
      M(1, "Gulamgiri, a book against caste oppression published in 1871, was written by", "Jyotiba Phule", ["B.R. Ambedkar", "E.V. Ramaswamy Naicker", "Tarabai Shinde"], "Phule wrote Gulamgiri to expose the injustices of the caste system."),
      M(1, "The Vernacular Press Act of 1878 was modelled on the", "Irish Press Laws", ["French Press Laws", "Roman Index", "Austrian rules for printers"], "The British government copied laws used in Ireland to curb the press."),
      M(1, "Bal Gangadhar Tilak was imprisoned in 1908 for writing in his paper", "Kesari", ["Bengal Gazette", "Sambad Kaumudi", "Samachar Chandrika"], "He wrote with sympathy about Punjab revolutionaries in Kesari, and his jailing led to widespread protests."),
      M(2, "Which of these was a drawback of handwritten manuscripts?", "They were slow and expensive to copy", ["They were available in unlimited numbers", "They could be printed in minutes", "They never got damaged"], "Manuscripts were fragile and could not circulate easily."),
      M(2, "Which movement followed the spread of printed copies of Luther's Ninety-Five Theses?", "The Protestant Reformation", ["The Industrial Revolution", "The Enlightenment", "The rise of Romanticism"], "Luther's criticism of the Catholic Church, spread by print, led to a split in the Church."),
      M(2, "Print popularised the ideas of which Enlightenment thinkers?", "Voltaire and Rousseau", ["Luther and Menocchio", "Hickey and Tilak", "Austen and Eliot"], "Their ideas about reason, liberty and equality reached a wide reading public."),
      M(2, "Jane Austen, the Brontë sisters and George Eliot were important as", "women novelists", ["children's authors", "newspaper owners", "founders of lending libraries"], "In the nineteenth century women became both readers and writers."),
      M(2, "In nineteenth-century England lending libraries were useful mainly for", "educating artisans and clerks", ["storing handwritten manuscripts", "banning cheap books", "teaching only Latin"], "These libraries helped white-collar workers and artisans educate themselves."),
      M(2, "Richard M. Hoe of New York perfected the", "power-driven cylindrical press", ["offset press", "steam hammer", "spinning jenny"], "The cylindrical press allowed thousands of pages to be printed in an hour."),
      M(2, "Which press of the late nineteenth century could print up to six colours at a time?", "The offset press", ["The cylindrical press", "The Gutenberg press", "The woodblock"], "The offset press made colour printing quicker."),
      M(2, "The first Tamil book was printed in 1579 at", "Cochin", ["Goa", "Madras", "Pondicherry"], "Portuguese missionaries brought the press to Goa and printed the Tamil book at Cochin; the first Malayalam book followed in 1713."),
      M(2, "James Augustus Hickey's Bengal Gazette began in", "1780", ["1713", "1821", "1878"], "Hickey edited it as a weekly, and it criticised the Company's officials."),
      M(3, "Arrange in time order: (a) Luther's Ninety-Five Theses, (b) Gutenberg's press, (c) Diamond Sutra printed in Japan, (d) Marco Polo brings woodblock knowledge to Italy.", "(c), (d), (b), (a)", ["(c), (b), (d), (a)", "(d), (c), (b), (a)", "(c), (d), (a), (b)"], "The dates are AD 868, 1295, the 1430s and 1517."),
      M(3, "Match author with work: (1) Rashsundari Debi, (2) Jyotiba Phule, (3) Kashibaba, (4) Tarabai Shinde and Pandita Ramabai. Works: (P) Gulamgiri, (Q) Chhote Aur Bade Ka Sawal, (R) Amar Jiban, (S) writing about the miserable lives of upper-caste women.", "1-R, 2-P, 3-Q, 4-S", ["1-P, 2-R, 3-Q, 4-S", "1-R, 2-P, 3-S, 4-Q", "1-Q, 2-P, 3-R, 4-S"], "Rashsundari Debi's Amar Jiban (1876), Phule's Gulamgiri (1871) and Kashibaba's work of 1938 are matched."),
      M(3, "After the 1857 revolt the colonial government grew hostile to the native press mainly because it", "saw such papers as a threat to British rule", ["wanted to sell more English newspapers", "found them too expensive", "disliked their printing methods"], "The hostility led to the Vernacular Press Act of 1878."),
      AR(2, "Print made the ideas of Enlightenment thinkers widely available.", "Printed books and journals carried their arguments to a larger reading public.", 0, "Print widened the audience, creating a culture of dialogue and debate."),
      AR(2, "The Church feared the spread of printing.", "Printed material could carry rebellious and irreligious thoughts.", 0, "Religious authorities worried about uncontrolled printing and drew up lists of prohibited books."),
      AR(3, "Print caused people to accept blindly all that they read.", "People read selectively and interpreted ideas in their own ways.", 3, "Print did not directly shape minds; readers chose and interpreted ideas, so the assertion is false."),
      AR(2, "Hand-printing in Japan began under Chinese influence.", "Buddhist missionaries from China brought hand-printing technology to Japan around AD 768-770.", 0, "The missionaries introduced the technique, which explains its Chinese origin."),
      AR(3, "Cheap paperbacks became common during the Depression of the 1930s.", "Publishers wanted to keep book sales going when people had less money.", 0, "Low-priced paperbacks kept readers buying books in hard times."),
    ],
    written: [
      W(2, "Who was Kitagawa Utamaro? What are ukiyo prints?", "Kitagawa Utamaro, born in Edo in 1753, was a famous Japanese artist.\nUkiyo prints are 'pictures of the floating world', showing scenes of everyday town life."),
      W(2, "Why were manuscripts not widely used in India before print?", "They were handwritten on palm leaves or handmade paper and were expensive and fragile.\nThey were produced slowly and could not circulate widely."),
      W(2, "Name the two Persian newspapers and one Gujarati newspaper that appeared in 1822.", "The Persian papers were Jam-i-Jahan Nama and Shamsul Akhbar.\nThe Gujarati paper was the Bombay Samachar."),
      W(2, "How did the Deoband Seminary use print? Mention one effect.", "Founded in 1867, it published thousands of fatwas telling Muslims how to conduct themselves in everyday life.\nThis helped spread religious guidance widely among Muslim readers."),
      W(3, "How did print encourage debates on religion in India? Give three examples.", "Rammohun Roy published Sambad Kaumudi from 1821 to argue for reform.\nOrthodox Hindus replied with Samachar Chandrika.\nThe Deoband Seminary published thousands of fatwas; the first printed edition of Tulsidas's Ramcharitmanas came from Calcutta in 1810."),
      W(3, "Describe three technological developments in printing in the nineteenth century.", "Richard M. Hoe of New York perfected the power-driven cylindrical press by the mid-nineteenth century, which printed far faster.\nThe offset press of the late nineteenth century could print up to six colours at a time.\nCheaper printing and new sales methods (serialised novels, cheap series, dust covers) followed."),
      W(3, "How did Martin Luther and print change religion in Europe? Give three points.", "In 1517 Luther wrote the Ninety-Five Theses criticising the practices of the Roman Catholic Church.\nPrinted copies spread quickly and many read them, leading to the Protestant Reformation.\nLuther praised printing as the ultimate gift of God and the greatest one."),
      W(3, "Explain three ways in which the Church and the state tried to control print in Europe and India.", "From 1558 the Roman Church kept an Index of Prohibited Books, and Menocchio was executed by the Inquisition for his views.\nThe British government passed the Vernacular Press Act in 1878, allowing censorship of reports and editorials and the seizure of presses.\nTilak was imprisoned in 1908 for his writings in Kesari."),
      W(5, "Trace the growth of print in India from the manuscript age to the nineteenth century.", "Before print, India had handwritten manuscripts on palm leaves or handmade paper; they were expensive and fragile.\nPortuguese missionaries brought the press to Goa in the mid-sixteenth century; the first Tamil book was printed at Cochin in 1579 and the first Malayalam book in 1713.\nJames Augustus Hickey began the weekly Bengal Gazette in 1780.\nIn the 1820s Indian-owned papers appeared, such as Rammohun Roy's Sambad Kaumudi (1821), two Persian papers and the Gujarati Bombay Samachar (1822).\nIn the nineteenth century print also carried debates on religion, caste and women's lives, and the colonial government answered with the Vernacular Press Act (1878)."),
      W(4, "Case study: In a nineteenth-century English town a clerk borrows a novel from a lending library every week, while his sister reads serialised stories in a magazine. Their neighbour, a factory worker, reads cheap pamphlets and writes down his life story.\n(i) What were lending libraries used for? (1)\n(ii) Name two women writers of the century. (1)\n(iii) How did print help working-class people? (2)", "(i) Lending libraries educated white-collar workers, artisans and lower-middle-class people. (1)\n(ii) Any two of Jane Austen, the Brontë sisters, George Eliot. (1)\n(iii) Any two: it made cheap reading material available; workers could educate themselves in libraries; some workers wrote political tracts and autobiographies. (2)", "case"),
    ]
  },
  });
})();
